// Garantiza que ningún mensaje ni payload enviado a Docentes/Tutores contenga datos de mora familiar
for (const item of $input.all()) {
  const d = item.json;
  item.json.es_alerta_pedagogica = ['ROJO', 'NARANJA'].includes(d.vista_rbac_docente_dece_sin_datos_financieros.semaforo_docente);
  item.json.es_alerta_colecturia = d.vista_rbac_colecturia_exclusiva_financiera.activar_flujo_colecturia_n8n;
  item.json.tiene_nee = d.necesidad_educativa_nee !== 'ninguna';
}
return $input.all();
